def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p, v): p.write_text(json.dumps(v, ensure_ascii=False, indent=2) + '\n')
freeze = PREP / 'author-native-candidate.final.freeze.json'
assert sha(freeze) == '36a3cd9763d06419dba9a1464a2b36ea62f4e88a539fcdcf7ff3cfacf0dcc790'
frozen = json.loads(freeze.read_text())
assert len(frozen['files']) == 195
for f in frozen['files']:
    assert 'sha256:' + sha(Path(f['path'])) == f['sha256'], f['path']
c = json.loads((ROUND / 'description-review-campaign.json').read_text())
b = c['batches'][0]
inp = [json.loads(v)['goal'] for v in (ROUND / 'batches' / (b['batchId'] + '.input.jsonl')).read_text().splitlines()]
assert len(inp) == 7 and not (OWN / 'results').exists()
assert c['bookDigest'] == 'sha256:50ef9c8068c84a2da5301d8961622a7390cec096ebd789a5bfc373037918e92a'
assert c['bundleFingerprint'] == 'sha256:1e1ab0094971d73c89f78b142911847af93462216f1b667e5f9818914d842f52'
