    rec.update(decision='keep', understandingEvidence=dict(zip(keys, ev)), rationale=rat, evidenceProfileContract='positive-understanding-evidence-v2', evidenceProfileRecommendation='create', recordStatus='candidate', reviewAuthority='ai_candidate')
    records.append(rec)
